function input(c,offset,bytes,label){const before=capture(c,"before input "+label);new Uint8Array(c.memory.buffer).set(bytes,c.base+offset);journal.push({context:c.ordinal,owner:c.owner,name:"input",offset,hex:bytes.toString("hex"),label,before,after:capture(c,"after input "+label)});}
function upload(c,address,bytes){input(c,140,bytes,"declared upload");host(c,"upload",[address,bytes.length]);for(let i=0;i<bytes.length;i++)c.known.set(address+i,bytes[i]);}
function known(c,address,length){return Buffer.from(Array.from({length},(_,i)=>c.known.get(address+i)??0));}
function readRam(c,address,length,label){const rows=[],bytes=Buffer.alloc(length);for(let i=0;i<length;i++){rows.push(host(c,"read8",[address+i],label+" byte"+i));bytes[i]=arena(c).readUInt32LE(120);assert.deepEqual(arena(c).subarray(100,140),helper(2,bytes[i],undefined,1));}assert.deepEqual(bytes,known(c,address,length),label+" equals declared RAM model");const row={context:c.ordinal,owner:c.owner,label,address,bytes:length,hex:bytes.toString("hex"),reads:rows};ram.push(row);return row;}
