function run(c,budget,label,next,reason=1,count=1,f,status=0,memoryTarget=true,exitVersion=2){const before=capture(c,"before generated "+label),expected=arena(c);if(status===0){expected.set(state(next));expected.set(exit(reason,count,f,exitVersion),56);if(f)expected.set(helper(f.access===1?2:4,0,f),100);else if(memoryTarget&&count)expected.set(helper(4),100);}assert.equal(c.run(c.base,c.base+56,budget,c.base+96),status,label);assert.deepEqual(arena(c),expected,"full arena "+label);generated++;retired+=status===0?count:0;const row={context:c.ordinal,owner:c.owner,name:"run",label,budget,status,before,after:capture(c,"after generated "+label)};journal.push(row);return row;}
