function copy(c,label,value,reason=1){const before=cpu(c),source=before.registers[6],destination=before.registers[7],w=window(destination),beforeRam=readRam(c,...w,"before "+label);host(c,"read16",[source],"declared WORD source");assert.equal(arena(c).readUInt32LE(120),value,"source equals independent literal");assert.deepEqual(arena(c).subarray(100,140),helper(2,value));const next={registers:[...before.registers],pc:(before.pc+2)>>>0,flags:before.flags},delta=before.flags&0x400?-2:2;next.registers[6]=(source+delta)>>>0;next.registers[7]=(destination+delta)>>>0;const row=run(c,1,label,next,reason);for(let i=0;i<2;i++)c.known.set(destination+i,word(value)[i]);const afterRam=readRam(c,...w,"after "+label);copies.push({context:c.ordinal,owner:c.owner,entries:c.entries,label,source,destination,value,before,next,run:row,beforeRam,afterRam});}
function compile(c,descriptors,tail=false){input(c,140,words(c.entries?descriptors.filter((_,i)=>i%2===0):descriptors),tail?"current tail descriptor; no CPU repair":"compiler descriptors");let binding;const name=c.owner==="replacement"?(c.entries?"compile_entries":"compile"):(c.entries?"compile_resident_entries":"compile_resident");host(c,name,c.entries?[descriptors.length/2,0]:[descriptors.length/2]);if(c.owner==="replacement")binding={generation:c.api.generation(),pointer:c.api.module_ptr()>>>0,length:c.api.module_len()>>>0};else{const b=arena(c);binding=Object.fromEntries(["low","high","pointer","length"].map((name,i)=>[name,b.readUInt32LE(148+i*4)]));}const bytes=Buffer.from(new Uint8Array(c.memory.buffer,binding.pointer,binding.length)),module=new WebAssembly.Module(bytes),guard=c.owner==="replacement"?"guard":"guard_resident",names=tail?[guard]:[guard,"read16",c.owner==="replacement"?"store16":"store_resident16"];assert.deepEqual(WebAssembly.Module.imports(module),[{module:"env",name:"memory",kind:"memory"},...names.map(name=>({module:"ring3",name,kind:"function"}))]);c.run=new WebAssembly.Instance(module,{env:{memory:c.memory},ring3:c.api}).exports.run;c.binding=binding;const file=c.owner+"-"+c.ordinal+(tail?"-tail":"")+".wasm";writeFileSync(join(output,file),bytes,{flag:"wx"});modules.push({context:c.ordinal,owner:c.owner,entries:c.entries,file,...binding,bytes:bytes.length,sha256:hash(bytes),imports:names});}
